# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DOĞRULUK (SIDK) VE GÜVENİLİRLİK (EMANET) AHLAKI (TDB.1.2)</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Doğruluk / Dürüstlük (Sıdk - الصِّدْقُ)</text>\n  <text x="44" y="98" font-size="11" fill="#334155">• Tanım: Özün, sözün ve davranışın</text>\n  <text x="44" y="114" font-size="11" fill="#334155">  birbiriyle uyumlu ve gerçek olması</text>\n  <text x="44" y="138" font-size="11" fill="#334155">• Zıddı: Yalan (Kizb) ve İkiyüzlülük (Nifak)</text>\n  <text x="44" y="162" font-size="11" fill="#334155">• Hûd Suresi 112. Ayet: "Emrolunduğun</text>\n  <text x="44" y="178" font-size="11" fill="#334155">  gibi dosdoğru ol! (فَاسْتَقِمْ كَمَا أُمِرْتَ)"</text>\n  <text x="183" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Doğru sözlü kişiye "Sâdık / Sıddîk" denir</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Güvenilirlik (Emanet - الْأَمَانَةُ)</text>\n  <text x="378" y="98" font-size="11" fill="#334155">• Tanım: Korunması istenen maddi ve</text>\n  <text x="378" y="114" font-size="11" fill="#334155">  manevi her hakkı (sır, mal, görev) koruma</text>\n  <text x="378" y="138" font-size="11" fill="#334155">• Zıddı: Hıyanet (Emanete ihanet etmek)</text>\n  <text x="378" y="162" font-size="11" fill="#334155">• Nisâ 58. Ayet: "Allah size emanetleri</text>\n  <text x="378" y="178" font-size="11" fill="#334155">  ehline (sahibine) vermenizi emreder"</text>\n  <text x="517" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Peygamberimizin Lakabı: Muhammedü\'l-Emîn</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ADALET (الْعَدْلُ), YARDIMSEVERLİK VE İNFAK AHLAKI</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">1. Adalet ve Hakkaniyet (الْعَدَالَةُ)</text>\n  <text x="44" y="98" font-size="11" fill="#334155">• Tanım: Herkese hakkını vermek, bir şeyi</text>\n  <text x="44" y="114" font-size="11" fill="#334155">  yerli yerine koymak (Zıddı: Zulüm)</text>\n  <text x="44" y="138" font-size="11" fill="#334155">• Nahl Suresi 90. Ayet: "Şüphesiz Allah</text>\n  <text x="44" y="154" font-size="11" fill="#334155">  adaleti, iyiliği (ihsanı) ve akrabaya</text>\n  <text x="44" y="170" font-size="11" fill="#334155">  yardım etmeyi emreder..."</text>\n  <text x="183" y="206" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Adalet mülkün (devletin ve toplumun) temelidir</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">2. Yardımseverlik, İnfak ve Îsâr</text>\n  <text x="378" y="98" font-size="11" fill="#334155">• İnfak: Allah rızası için malından harcama</text>\n  <text x="378" y="118" font-size="11" fill="#334155">• Sadaka-i Cariye: Kişi öldükten sonra da</text>\n  <text x="378" y="134" font-size="11" fill="#334155">  sevabı devam eden hayır (çeşme, okul, ilim)</text>\n  <text x="378" y="158" font-size="11" fill="#334155">• Îsâr (Diğergamlık): Kendisi muhtaç</text>\n  <text x="378" y="174" font-size="11" fill="#334155">  olduğu hâlde kardeşini kendine tercih etme</text>\n  <text x="517" y="206" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Sağ elin verdiğini sol el görmemelidir</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSLAM VE AHLAK TEMASI BÜTÜNCÜL ÖZET HARİTASI</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Ahlakın Kaynakları</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Kur\'an-ı Kerim (İlahi Rehber)</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• Peygamberimizin Sünneti</text>\n  <text x="40" y="136" font-size="10.5" fill="#475569">  (Üsve-i Hasene / En güzel örnek)</text>\n  <text x="40" y="160" font-size="11" fill="#334155">• İhsan ve Takva Bilinci</text>\n  <text x="40" y="182" font-size="11" fill="#334155">• Öz Denetim ve Nefis Muhasebesi</text>\n  <text x="130" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">"Ben güzel ahlakı tamamlamak</text>\n  <text x="130" y="230" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">için gönderildim." (Hadis)</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Bireysel ve Toplumsal Erdemler</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Sabır ve Şükür (İki kanat)</text>\n  <text x="260" y="120" font-size="11" fill="#334155">• Hoşgörü (Müsamaha) ve</text>\n  <text x="260" y="136" font-size="11" fill="#334155">  Affedicilik</text>\n  <text x="260" y="160" font-size="11" fill="#334155">• Doğruluk (Sıdk) ve Emanet</text>\n  <text x="260" y="182" font-size="11" fill="#334155">• Adalet, İnfak ve Yardımseverlik</text>\n  <text x="350" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Ahlak-ı Hamîde (Övülen Ahlak)</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="570" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b91c1c">Kaçınılması Gereken Kötü Huylar</text>\n  <text x="480" y="98" font-size="11" fill="#334155">• Yalan (Kizb) ve İftira</text>\n  <text x="480" y="120" font-size="11" fill="#334155">• Emanete Hıyanet ve Hile</text>\n  <text x="480" y="142" font-size="11" fill="#334155">• Gıybet (Dedikodu) ve Tecessüs</text>\n  <text x="480" y="164" font-size="11" fill="#334155">• Haset (Kıskançlık) ve Kibir</text>\n  <text x="480" y="186" font-size="11" fill="#334155">• Zulüm, Cimrilik ve Riya</text>\n  <text x="570" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#991b1b">Ahlak-ı Zemîme (Yerilen Huylar)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
